// Assets/CoreEngine/WorldGen/TerrainGenChunkSource.cs
//
// V1 of the V/H phase (design doc §11; owner go-ahead 2026-09-25/26): chunks
// generated by TERRAINGEN for sizeClass 2 worlds. The legacy generator
// (ChunkGeneratorFull) keeps sizeClass 0/1 byte-identical -- StreamManager
// picks the source by WorldMetaData.sizeClass (GenerateBaseline).
//
// Coordinates: engine voxel == TerrainGen voxel, Y absolute (sizeClass 2's
// sea surface is at Y 5120; the world is 0..~11,000 voxels tall, chunk layers
// 0..86). Streaming those layers is V2; this file only makes the chunk.
//
// Per chunk: a Burst ColumnJob samples S, MaxStep and D's column detail for
// the 128^2 columns; a chunk wholly above every column's ground and water is
// returned as UNIFORM AIR right there (V2's air fast path). Otherwise a
// VoxelJob evaluates D's material for every voxel with the brick cull record
// (exact by construction, DetailCullTests), mapped to engine material ids.
// Bricks of one material are stored as that material (the sticky-note
// economy); the rest get a pooled 512-byte body, laid out exactly as
// ChunkGeneratorFull lays them out.
//
// BRICK SKIP (engine step 15, task 82b; ENGINE_PHASE_PLAN.md row 15): before
// the per-voxel pass, a brick wholly above its 64 columns' max(ground, water,
// sea) is uniform air outright, and a brick wholly above or wholly below every
// column's ground asks DetailField.UniformSamples per column whether the column
// data PROVES one material for all its voxels (water, lake, stone, soil...).
// Proven bricks are written as the uniform brick they would have been; the
// rest take the per-voxel pass unchanged. Output is byte-identical with the
// skip on or off (BrickSkip; BrickSkipTests). Same in GenerateShellChunk.
//
// MATERIALS: today the GenMat codes collapse onto the existing engine ids
// (the far band's mapping, FarField.GenToEngine) -- the ~45 palette-D strata,
// soil and stamp materials are V1b and change only that table.
//
// The column pass depends only on (x, z): StreamManager hands a column's layers
// to one worker, which reuses its own ColumnPass across them (task 30).
//
// THREADING: Generate runs on StreamManager's worker threads concurrently. The
// map arrays are shared READ-ONLY; each call owns its job buffers (or its
// thread's ColumnPass); the pool and allocator it writes are the worker's own
// scratch (single-writer, CLAUDE.md).
using System;
using Unity.Burst;
using Unity.Collections;
using Unity.Collections.LowLevel.Unsafe;
using Unity.Jobs;
using Unity.Mathematics;
using VoxelEngine.Memory;

namespace VoxelEngine.WorldGen
{
    public sealed partial class TerrainGenChunkSource : IDisposable
    {
        public const byte SIZE_CLASS = 2;
        public const int BRICK_GEOLOGY_DEPTH = 200;
        public readonly TerrainGen.TerrainSpec Spec;
        public readonly TerrainGen.Offsets O;
        public readonly TerrainGen.WorldMap Map;
        private NativeArray<float> _h, _r, _w;
        private NativeArray<byte> _cls;   // map water class: ShapeField's lake rims (v4)
        private NativeArray<ushort> _flow; // v4 river flow bits (task 76; length 1 = none)
        private NativeArray<byte> _ore;   // per map cell ore multiplier (gameplay step 3; zeros on v3)
        private NativeArray<byte> _toEngine;

        public TerrainGenChunkSource(uint seed) : this(seed, MapVersionArg()) { }

        /// -mapversion N (surface rebuild B1): which TerrainGen map recipe a
        /// tg2 world uses -- 4 = v3 + the world record + larger biomes. Absent
        /// or unparsable = 0, the default (v4 since 2026-10-09, owner Q35 6a;
        /// -mapversion 3 = the pre-rebuild map). Last match wins, like
        /// PlaygroundCapture's ArgValue.
        public static int MapVersionArg()
        {
            string[] a = Environment.GetCommandLineArgs();
            int v = 0;
            for (int i = 0; i + 1 < a.Length; i++)
                if (a[i] == "-mapversion" && int.TryParse(a[i + 1], out int p)) v = p;
            return v;
        }

        public TerrainGenChunkSource(uint seed, int mapVersion)
        {
            // R1 BRICK GEOLOGY (V0, design doc §11/§15): below 20 m under the
            // column top, one strata decision per 8^3 brick instead of per
            // voxel. Measured (V0): shallow chunks 499 -> 97 dense bricks, the
            // underworld 993 -> 95. Only dug-out or cave walls deeper than 20 m
            // show it, as 0.8 m steps in the bands. It is what fits the band
            // in the owner's 3 GB.
            var spec = TerrainGen.TerrainSpec.SizeClass2(seed, mapVersion);
            spec.brickGeologyDepth = BRICK_GEOLOGY_DEPTH;
            Spec = spec;
            O = TerrainGen.Offsets.For(in spec);   // v4: carries the biome scale
            Map = TerrainGen.WorldMap.Build(Spec);
            _h = new NativeArray<float>(Map.Height, Allocator.Persistent);
            _r = new NativeArray<float>(Map.Rough, Allocator.Persistent);
            _w = new NativeArray<float>(Map.Water, Allocator.Persistent);
            _cls = new NativeArray<byte>(Map.WaterClass, Allocator.Persistent);
            _flow = new NativeArray<ushort>(Map.FlowDir ?? new ushort[1], Allocator.Persistent);
            _ore = new NativeArray<byte>(TerrainGen.OreTable.DensityPlane(Map.Record, Spec.mapCells), Allocator.Persistent);
            _toEngine = new NativeArray<byte>(256, Allocator.Persistent);
            for (int i = 0; i < 256; i++) _toEngine[i] = VoxelEngine.Rendering.FarField.GenToEngine((byte)i);

            // Highest chunk layer that can hold anything but air: the map's
            // highest macro height and roughness, every detail octave at full
            // amplitude, and STAMP_RISE_BOUND for stamps (the tallest lifts a
            // column ~180 voxels above its site's ground). V2 admits no layer
            // above it; TopLayerIsABound_OnTheMap checks it.
            float maxMacro = 0f, maxRough = 0f;
            for (int i = 0; i < Map.Height.Length; i++) { maxMacro = math.max(maxMacro, Map.Height[i]); maxRough = math.max(maxRough, Map.Rough[i]); }
            float detailMax = 0f;
            for (int i = 0; i < TerrainGen.ShapeField.DETAIL_OCTAVES; i++) detailMax += TerrainGen.ShapeField.Amplitude(i);
            MaxContentY = Spec.seaLevelY + (int)math.ceil(maxMacro + detailMax * maxRough) + STAMP_RISE_BOUND;
            TopLayerChunkY = MaxContentY >> 7;
        }

        public const int STAMP_RISE_BOUND = 400;
        /// Upper bound on any non-air voxel's Y (see the constructor).
        public readonly int MaxContentY;
        public readonly int TopLayerChunkY;

        public void Dispose()
        {
            if (_h.IsCreated) _h.Dispose();
            if (_r.IsCreated) _r.Dispose();
            if (_w.IsCreated) _w.Dispose();
            if (_cls.IsCreated) _cls.Dispose();
            if (_flow.IsCreated) _flow.Dispose();
            if (_ore.IsCreated) _ore.Dispose();
            if (_toEngine.IsCreated) _toEngine.Dispose();
            Map?.Dispose();
        }

        /// The engine material of every voxel of chunk `coord`, x fastest then
        /// z then y within a brick-major order the caller reads with Index().
        public static int Index(int x, int y, int z) => (y << 14) | (z << 7) | x;

        /// Chunks generated as uniform air without the voxel pass (whole chunk
        /// above every column's ground and water) -- diagnostics for V2.
        public int AirFastPathTotal => _airFast;
        private int _airFast;

        /// max(ground, still water, sea) over each chunk COLUMN's 128^2 columns,
        /// keyed by (cx, cz). The same for every layer of the column, so once
        /// one layer has run the column pass, every layer above it knows it is
        /// air without one. A MEMO OF A PURE FUNCTION, not world state: two
        /// workers racing on one key compute and store the same value, so no
        /// ordering or lock matters (CLAUDE.md's single-writer rule concerns
        /// ChunkStore, the pools and the chunk table, none of which this is).
        /// Bounded: cleared past COLUMN_TOP_MEMO_MAX (the whole 8 km world is
        /// 390,625 columns; one ring is ~1,000).
        private readonly System.Collections.Concurrent.ConcurrentDictionary<long, int> _columnTop =
            new System.Collections.Concurrent.ConcurrentDictionary<long, int>();
        private const int COLUMN_TOP_MEMO_MAX = 65536;
        private static long ColumnKey(int3 c) => ((long)c.x << 32) | (uint)c.z;

        private static void MakeAir(Chunk chunk)
        {
            chunk.isUniform = true;
            chunk.uniformMaterial = Materials.Air;
        }

        /// ColumnJob runs since construction (task 30's "ColumnJob runs per
        /// column" diagnostic; a shared pass is not counted again).
        public int ColumnPassTotal => _columnPasses;
        private int _columnPasses;

        /// COLUMN-PASS SHARING (task 30; PLAN_COARSE_FIRST_GEN.md section 6).
        /// ColumnJob's output depends only on the chunk COLUMN (cx, cz) -- it
        /// reads origin.x and origin.z, never y -- yet it was ~0.60 of a
        /// chunk's Generate and ran once per LAYER. A ColumnPass holds ONE
        /// column's result so every layer of that column reuses it.
        /// OWNED BY ONE THREAD (a stream worker for its lifetime, or a test):
        /// never shared, so no lock and no publication race. Bound: one column,
        /// Bytes (~2.6 MB), per owner. Bit-identical by construction -- the same
        /// Burst job writes the same arrays; ColumnPassSharing_IsByteIdentical
        /// checks it.
        public sealed class ColumnPass : IDisposable
        {
            internal NativeArray<TerrainGen.ColumnSample> colS;
            internal NativeArray<float> colSt;
            internal NativeArray<TerrainGen.DetailField.ColumnDetail> colCd;
            internal NativeArray<int> top;
            internal bool valid;
            internal int cx, cz;
            /// ColumnJob runs into this pass (diagnostics).
            public int Runs;

            public ColumnPass(Allocator a = Allocator.Persistent)
            {
                const int E = EngineConfig.CHUNK_EDGE_VOXELS;
                colS = new NativeArray<TerrainGen.ColumnSample>(E * E, a, NativeArrayOptions.UninitializedMemory);
                colSt = new NativeArray<float>(E * E, a, NativeArrayOptions.UninitializedMemory);
                colCd = new NativeArray<TerrainGen.DetailField.ColumnDetail>(E * E, a, NativeArrayOptions.UninitializedMemory);
                top = new NativeArray<int>(1, a);
            }

            public bool Holds(int3 coord) => valid && cx == coord.x && cz == coord.z;

            /// Bytes one pass holds.
            public static long Bytes
            {
                get
                {
                    const int E = EngineConfig.CHUNK_EDGE_VOXELS;
                    return (long)E * E * (UnsafeUtility.SizeOf<TerrainGen.ColumnSample>() + sizeof(float)
                                          + UnsafeUtility.SizeOf<TerrainGen.DetailField.ColumnDetail>()) + sizeof(int);
                }
            }

            public void Dispose()
            {
                valid = false;
                if (colS.IsCreated) colS.Dispose();
                if (colSt.IsCreated) colSt.Dispose();
                if (colCd.IsCreated) colCd.Dispose();
                if (top.IsCreated) top.Dispose();
            }
        }

        public void Generate(int3 coord, Chunk chunk, ChunkHandleAllocator allocator, BrickDataPool pool, object allocLock)
            => Generate(coord, chunk, allocator, pool, allocLock, null);

        /// Task 82b's brick skip (header). On by default; tests turn it off for
        /// the byte-identical and timing comparisons. Read at each call.
        public bool BrickSkip = true;

        /// Brick-skip diagnostics since construction, summed by every thread:
        /// [0..3] Generate, [4..7] GenerateShellChunk, each = bricks proven
        /// uniform AIR, FLUID (water/lava), SOLID, and bricks that reached the
        /// voxel pass stage (4096 per chunk that was not wholly air).
        public readonly long[] SkipStats = new long[8];

        private void AddSkipStats(NativeArray<int> st, int at)
        {
            for (int i = 0; i < 4; i++) System.Threading.Interlocked.Add(ref SkipStats[at + i], st[i]);
        }

        /// `pass` (may be null = a private one-shot pass, the old behaviour):
        /// reused when it already holds coord's column, refilled otherwise.
        public void Generate(int3 coord, Chunk chunk, ChunkHandleAllocator allocator, BrickDataPool pool, object allocLock, ColumnPass pass)
        {
            const int E = EngineConfig.CHUNK_EDGE_VOXELS;
            chunk.coord = coord;
            chunk.isUniform = false;

            bool shared = pass != null && pass.Holds(coord);
            if (!shared && _columnTop.TryGetValue(ColumnKey(coord), out int knownTop) && coord.y * E > knownTop)
            {
                MakeAir(chunk);
                System.Threading.Interlocked.Increment(ref _airFast);
                return;
            }

            ColumnPass own = pass == null ? new ColumnPass(Allocator.TempJob) : null;
            var cp = pass ?? own;
            NativeArray<byte> mats = default, uniform = default;
            NativeArray<bool> isUniform = default;
            NativeArray<int> stats = default;
            try
            {
                if (!shared)
                {
                    cp.valid = false;
                    new ColumnJob
                    {
                        h = _h, r = _r, w = _w, cls = _cls, flow = _flow, ore = _ore, spec = Spec, o = O, origin = coord * E,
                        colS = cp.colS, colSt = cp.colSt, colCd = cp.colCd, top = cp.top,
                    }.Run();
                    cp.cx = coord.x; cp.cz = coord.z; cp.valid = true; cp.Runs++;
                    System.Threading.Interlocked.Increment(ref _columnPasses);
                    if (_columnTop.Count > COLUMN_TOP_MEMO_MAX) _columnTop.Clear();
                    _columnTop[ColumnKey(coord)] = cp.top[0];
                }
                var colS = cp.colS; var colSt = cp.colSt; var colCd = cp.colCd;

                // V2 AIR FAST PATH. Above a column's top solid voxel D returns only
                // air or water (DetailField.Material's first block), so a chunk
                // wholly above every column's max(ground, still water, sea) is
                // uniform air by construction -- no voxel pass, no brick table.
                // Most of a vertically streamed ring is exactly this.
                if (coord.y * E > cp.top[0])
                {
                    MakeAir(chunk);
                    System.Threading.Interlocked.Increment(ref _airFast);
                    return;
                }

                if (allocLock != null) { lock (allocLock) { chunk.bricks = allocator.Alloc(); } }
                else chunk.bricks = allocator.Alloc();

                mats = new NativeArray<byte>(E * E * E, Allocator.TempJob, NativeArrayOptions.UninitializedMemory);
                uniform = new NativeArray<byte>(EngineConfig.BRICKS_PER_CHUNK, Allocator.TempJob);
                isUniform = new NativeArray<bool>(EngineConfig.BRICKS_PER_CHUNK, Allocator.TempJob);
                stats = new NativeArray<int>(4, Allocator.TempJob);
                new VoxelJob
                {
                    toEngine = _toEngine, spec = Spec, o = O, origin = coord * E,
                    colS = colS, colSt = colSt, colCd = colCd,
                    mats = mats, brickMat = uniform, brickUniform = isUniform,
                    skip = BrickSkip, stats = stats,
                }.Run();
                AddSkipStats(stats, 0);

                var raw = pool.RawData;
                for (int by = 0; by < 16; by++)
                for (int bz = 0; bz < 16; bz++)
                for (int bx = 0; bx < 16; bx++)
                {
                    int bi = (bz << 8) | (by << 4) | bx;
                    if (isUniform[bi]) { chunk.bricks[bi].data = uniform[bi]; continue; }
                    int poolIdx;
                    if (allocLock != null) { lock (allocLock) { poolIdx = pool.Alloc(); } }
                    else poolIdx = pool.Alloc();
                    chunk.bricks[bi].data = 0x80000000u | (uint)poolIdx;
                    int start = poolIdx * 512;
                    for (int vy = 0; vy < 8; vy++)
                    for (int vz = 0; vz < 8; vz++)
                    for (int vx = 0; vx < 8; vx++)
                        raw[start + ((vz << 6) | (vy << 3) | vx)] = mats[Index((bx << 3) + vx, (by << 3) + vy, (bz << 3) + vz)];
                }
            }
            finally
            {
                own?.Dispose();
                if (mats.IsCreated) mats.Dispose();
                if (uniform.IsCreated) uniform.Dispose();
                if (isUniform.IsCreated) isUniform.Dispose();
                if (stats.IsCreated) stats.Dispose();
            }
        }

        [BurstCompile(FloatMode = FloatMode.Strict, FloatPrecision = FloatPrecision.High, CompileSynchronously = true)]
        private struct ColumnJob : IJob
        {
            [ReadOnly] public NativeArray<float> h, r, w;
            [ReadOnly] public NativeArray<byte> cls;
            [ReadOnly] public NativeArray<ushort> flow;
            [ReadOnly] public NativeArray<byte> ore;
            public TerrainGen.TerrainSpec spec; public TerrainGen.Offsets o;
            public int3 origin;
            public NativeArray<TerrainGen.ColumnSample> colS;
            [WriteOnly] public NativeArray<float> colSt;
            [WriteOnly] public NativeArray<TerrainGen.DetailField.ColumnDetail> colCd;
            public NativeArray<int> top;   // [0] = max over columns of max(height, water, sea)

            public unsafe void Execute()
            {
                const int E = 128;
                var map = new TerrainGen.MapView
                {
                    height = (float*)h.GetUnsafeReadOnlyPtr(), rough = (float*)r.GetUnsafeReadOnlyPtr(),
                    water = (float*)w.GetUnsafeReadOnlyPtr(), waterClass = (byte*)cls.GetUnsafeReadOnlyPtr(),
                    flowDir = flow.Length > 1 ? (ushort*)flow.GetUnsafeReadOnlyPtr() : null,   // task 76
                    cells = spec.mapCells, cellVoxels = spec.mapCellVoxels,
                };
                // S on a 130^2 grid (the chunk's columns plus a one-column
                // border). MaxStep(x, z, 1) is max |S(neighbour) - S(centre)|
                // over the four neighbours at +-1 voxel -- which ARE the
                // neighbouring columns' own samples, at the same float
                // coordinates ((x + 0.5f) + 1 == (x + 1) + 0.5f exactly for any
                // |x| < 2^22), so reading them from the grid is bit-identical to
                // calling MaxStep and saves four full Samples per column. The
                // exactness test compares against a reference that calls
                // MaxStep itself.
                const int G = E + 2;
                var hg = new NativeArray<int>(G * G, Allocator.Temp, NativeArrayOptions.UninitializedMemory);
                for (int k = -1; k <= E; k++)
                for (int i = -1; i <= E; i++)
                {
                    int x = origin.x + i, z = origin.z + k;
                    var c = TerrainGen.ShapeField.Sample(in spec, in map, in o, x + 0.5f, z + 0.5f, 1);
                    hg[(k + 1) * G + i + 1] = c.height;
                    if (i >= 0 && i < E && k >= 0 && k < E) colS[k * E + i] = c;
                }
                int maxTop = spec.seaLevelY;
                for (int k = 0; k < E; k++)
                for (int i = 0; i < E; i++)
                {
                    int x = origin.x + i, z = origin.z + k, ci = k * E + i, gi = (k + 1) * G + i + 1;
                    int ch = hg[gi];
                    int m = math.max(math.max(math.abs(hg[gi + 1] - ch), math.abs(hg[gi - 1] - ch)),
                                     math.max(math.abs(hg[gi + G] - ch), math.abs(hg[gi - G] - ch)));
                    colSt[ci] = m / 1f;
                    var cd = TerrainGen.DetailField.PrepareColumn(in spec, in o, x, z);
                    if (cd.oreMul != 0) cd.oreMul = ore[TerrainGen.Ores.CellIndex(x, z, spec.mapCells, spec.mapCellVoxels)];
                    colCd[ci] = cd;
                    var c = colS[ci];
                    maxTop = math.max(maxTop, math.max(c.height, c.water));
                }
                hg.Dispose();
                top[0] = maxTop;
            }
        }

        [BurstCompile(FloatMode = FloatMode.Strict, FloatPrecision = FloatPrecision.High, CompileSynchronously = true)]
        private struct VoxelJob : IJob
        {
            [ReadOnly] public NativeArray<byte> toEngine;
            public TerrainGen.TerrainSpec spec; public TerrainGen.Offsets o;
            public int3 origin;
            [ReadOnly] public NativeArray<TerrainGen.ColumnSample> colS;
            [ReadOnly] public NativeArray<float> colSt;
            [ReadOnly] public NativeArray<TerrainGen.DetailField.ColumnDetail> colCd;
            [WriteOnly] public NativeArray<byte> mats;
            public NativeArray<byte> brickMat;
            public NativeArray<bool> brickUniform;
            public bool skip;
            public NativeArray<int> stats;   // task 82b: SkipStats' four counts for this chunk

            public void Execute()
            {
                const int E = 128;
                var bTop = new NativeArray<int>(256, Allocator.Temp, NativeArrayOptions.UninitializedMemory);
                var bMinH = new NativeArray<int>(256, Allocator.Temp, NativeArrayOptions.UninitializedMemory);
                var bMaxH = new NativeArray<int>(256, Allocator.Temp, NativeArrayOptions.UninitializedMemory);
                if (skip) BrickColumnBounds(in spec, colS, bTop, bMinH, bMaxH);
                stats[3] += EngineConfig.BRICKS_PER_CHUNK;
                for (int by = 0; by < 16; by++)
                for (int bz = 0; bz < 16; bz++)
                for (int bx = 0; bx < 16; bx++)
                {
                    int bi = (bz << 8) | (by << 4) | bx;
                    int bc = (bz << 4) | bx, yLo = origin.y + (by << 3);
                    if (skip && yLo > bTop[bc])
                    {
                        brickUniform[bi] = true; brickMat[bi] = toEngine[TerrainGen.GenMat.Air];
                        stats[0]++;
                        continue;
                    }
                    var cr = TerrainGen.DetailField.CullBrick(in spec, in o, origin.x + (bx << 3), yLo, origin.z + (bz << 3));
                    if (skip && (yLo + 7 <= bMinH[bc] || yLo > bMaxH[bc]))
                    {
                        byte g = ProveBrick(in spec, colS, colSt, colCd, origin, 0, 0, bx, bz, yLo, cr.noPocket,
                                            cr.hasGeo, cr.geoDeep, cr.geoCavern, cr.geoUnder);
                        if (g != 255)
                        {
                            brickUniform[bi] = true; brickMat[bi] = toEngine[g];
                            stats[SkipKind(g)]++;
                            continue;
                        }
                    }
                    byte first = 0; bool uni = true;
                    for (int vz = 0; vz < 8; vz++)
                    for (int vx = 0; vx < 8; vx++)
                    {
                        int lx = (bx << 3) + vx, lz = (bz << 3) + vz, ci = lz * E + lx;
                        var c = colS[ci]; var cd = colCd[ci]; float st = colSt[ci];
                        for (int vy = 0; vy < 8; vy++)
                        {
                            int ly = (by << 3) + vy;
                            byte g = TerrainGen.DetailField.Material(in spec, in o, in c, in cd, st,
                                origin.x + lx, origin.y + ly, origin.z + lz, in cr);
                            byte m = toEngine[g];
                            mats[(ly << 14) | (lz << 7) | lx] = m;
                            if (vz == 0 && vx == 0 && vy == 0) first = m;
                            else if (m != first) uni = false;
                        }
                    }
                    brickUniform[bi] = uni;
                    brickMat[bi] = first;
                }
                bTop.Dispose(); bMinH.Dispose(); bMaxH.Dispose();
            }
        }

        // ---- Task 82b: the brick skip's helpers, shared by VoxelJob and ShellVoxelJob ----

        /// Per brick column (bz << 4 | bx) of a chunk's 128^2 sampled columns:
        /// the max of max(ground, water, sea), the min and the max ground.
        private static void BrickColumnBounds(in TerrainGen.TerrainSpec spec, NativeArray<TerrainGen.ColumnSample> colS,
                                              NativeArray<int> top, NativeArray<int> minH, NativeArray<int> maxH)
        {
            for (int i = 0; i < 256; i++) { top[i] = spec.seaLevelY; minH[i] = int.MaxValue; maxH[i] = int.MinValue; }
            for (int lz = 0; lz < 128; lz++)
            for (int lx = 0; lx < 128; lx++)
            {
                var c = colS[(lz << 7) | lx];
                int b = ((lz >> 3) << 4) | (lx >> 3);
                top[b] = math.max(top[b], math.max(c.height, c.water));
                minH[b] = math.min(minH[b], c.height);
                maxH[b] = math.max(maxH[b], c.height);
            }
        }

        /// The GenMat every sample of brick column (bx, bz) gets at the 8 sample
        /// heights from yLo (step 2^shift), from its 64 columns, or 255.
        private static byte ProveBrick(in TerrainGen.TerrainSpec spec, NativeArray<TerrainGen.ColumnSample> colS,
                                       NativeArray<float> colSt, NativeArray<TerrainGen.DetailField.ColumnDetail> colCd,
                                       int3 origin, int shift, int half, int bx, int bz, int yLo, bool noPocket,
                                       bool geoExact, float geoDeep, float geoCavern, float geoUnder)
        {
            byte m = 255;
            for (int vz = 0; vz < 8; vz++)
            for (int vx = 0; vx < 8; vx++)
            {
                int lx = (bx << 3) + vx, lz = (bz << 3) + vz, ci = (lz << 7) | lx;
                var c = colS[ci]; var cd = colCd[ci];
                byte g = TerrainGen.DetailField.UniformSamples(in spec, in c, in cd, colSt[ci],
                    origin.x + (lx << shift) + half, origin.z + (lz << shift) + half, yLo, 1 << shift, 8, noPocket,
                    geoExact, geoDeep, geoCavern, geoUnder);
                if (g == 255 || (m != 255 && g != m)) return 255;
                m = g;
            }
            return m;
        }

        /// SkipStats slot of a proven brick's material: 0 air, 1 fluid, 2 solid.
        private static int SkipKind(byte g)
            => g == TerrainGen.GenMat.Air ? 0 : (g == TerrainGen.GenMat.Water || g == TerrainGen.GenMat.Lava) ? 1 : 2;
    }
}
